    private DragLayout drag;private ScrollView scroller;private int starts,moves,finishes,cancels,taps;private long down;
    private void send(int action,float x,float y){int[] origin=new int[2];drag.getLocationOnScreen(origin);if(action==MotionEvent.ACTION_DOWN)down=SystemClock.uptimeMillis();MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x+origin[0],y+origin[1],0);event.offsetLocation(-origin[0],-origin[1]);drag.dispatchTouchEvent(event);event.recycle();}
